DO $$ BEGIN CREATE TYPE "user_role" AS ENUM ('ADMIN','CUSTOMER','WORKER','OPERATOR'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "verification_level" AS ENUM ('V0','V1','V2','V3','V4','V5','V6'); EXCEPTION WHEN duplicate_object THEN null; END $$;
CREATE TABLE IF NOT EXISTS "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"email" text NOT NULL UNIQUE,"password_hash" text NOT NULL,"full_name" text NOT NULL,"phone" text,"role" "user_role" NOT NULL,"active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "customer_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE cascade,"customer_type" text NOT NULL DEFAULT 'individual',"company_name" text,"verified" boolean NOT NULL DEFAULT false,"default_location" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "worker_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE cascade,"verification_level" "verification_level" NOT NULL DEFAULT 'V0',"skills" jsonb NOT NULL DEFAULT '[]'::jsonb,"service_areas" jsonb NOT NULL DEFAULT '[]'::jsonb,"rating" integer NOT NULL DEFAULT 0,"completed_jobs" integer NOT NULL DEFAULT 0,"available" boolean NOT NULL DEFAULT false,"created_at" timestamptz NOT NULL DEFAULT now());
